refentry.refsect1:
&reftitle.returnvalues;


 Questa funzione restituisce la distanza di Levenshtein tra le
 due stringhe passate come argomenti.

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Prima di questa versione, levenshtein doveva essere chiamata
     con due o con cinque argomenti.




    8.0.0

     Prima di questa versione, levenshtein restituiva -1
     se una delle stringhe passate come argomenti era più lunga di 255 caratteri.

  &reftitle.examples;



    Esempio di levenshtein


<?php
// parola inserita con un errore di ortografia
$input = 'carrrot';

// array di parole con cui confrontarla
$words  = array('apple','pineapple','banana','orange',
                'radish','carrot','pea','bean','potato');

// nessuna distanza minima ancora trovata
$shortest = -1;

// scorre le parole per trovare la più vicina
foreach ($words as $word) {

    // calcola la distanza tra la parola inserita
    // e la parola corrente
    $lev = levenshtein($input, $word);

    // controlla se c'è una corrispondenza esatta
    if ($lev == 0) {

        // la parola più vicina è questa (corrispondenza esatta)
        $closest = $word;
        $shortest = 0;

        // esce dal ciclo; è stata trovata una corrispondenza esatta
        break;
    }

    // se questa distanza è minore della distanza minima
    // trovata finora, OPPURE se non è ancora stata trovata una parola più vicina
    if ($lev <= $shortest || $shortest < 0) {
        // imposta la corrispondenza più vicina e la distanza minima
        $closest  = $word;
        $shortest = $lev;
    }
}

echo "Parola inserita: $input\n";
if ($shortest == 0) {
    echo "Trovata corrispondenza esatta: $closest\n";
} else {
    echo "Forse si intendeva: $closest?\n";
}

?>


    &example.outputs;


Parola inserita: carrrot
Forse si intendeva: carrot?
